selector_to_html = {"a[href=\"../glossary.html#term-dosbarth\"]": "<dt id=\"term-dosbarth\">dosbarth</dt><dd><p>class</p></dd>", "a[href=\"../glossary.html#term-arddull-rhaglennu-swyddogaethol\"]": "<dt id=\"term-arddull-rhaglennu-swyddogaethol\">arddull rhaglennu swyddogaethol</dt><dd><p>functional programming style</p></dd>", "a[href=\"#mae-gwrthrychau-n-gyfnewidiol\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.4. </span>Mae Gwrthrychau\u2019n Gyfnewidiol<a class=\"headerlink\" href=\"#mae-gwrthrychau-n-gyfnewidiol\" title=\"Link to this heading\">#</a></h2><p>Tybiwch eich bod yn mynd i weld ffilm, fel <em>Monty Python and the Holy\nGrail</em>, sy\u2019n dechrau am <code class=\"docutils literal notranslate\"><span class=\"pre\">9:20</span> <span class=\"pre\">PM</span></code> ac yn para <code class=\"docutils literal notranslate\"><span class=\"pre\">92</span></code> munud, sef awr <code class=\"docutils literal notranslate\"><span class=\"pre\">32</span></code>\nmunud. Pryd fydd y ffilm yn gorffen?</p><p>Yn gyntaf, byddwn yn creu gwrthrych <code class=\"docutils literal notranslate\"><span class=\"pre\">Time</span></code> sy\u2019n cynrychioli\u2019r amser\ncychwyn.</p>", "a[href=\"chap11.html#section-debugging-11\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">11.9. </span>Dadnamu<a class=\"headerlink\" href=\"#dadnamu\" title=\"Link to this heading\">#</a></h2><p>Mae rhestri, geiriaduron, a th\u0175pls yn <strong><a class=\"reference internal\" href=\"../glossary.html#term-strwythur-data\"><span class=\"xref std std-term\">strwythur data</span></a></strong>. Yn y\nbennod hon rydym yn dechrau gweld strwythurau data cyfansawdd, fel rhestri\no d\u0175pls, neu eiriaduron sy\u2019n cynnwys t\u0175pls fel allweddi a rhestri fel\ngwerthoedd. Mae strwythurau data cyfansawdd yn ddefnyddiol, ond maent yn\ndueddol o achosi gwallau pan fydd strwythur data o\u2019r math, maint, neu\nstrwythur anghywir. Er enghraifft, os yw swyddogaeth yn disgwyl rhestr o\ngyfanrifau a chi\u2019n rhoi cyfanrif plaen iddi (nid mewn rhestr), mae\u2019n debygol\nna fydd yn gweithio.</p><p>I helpu dadnamu\u2019r mathau hyn o wallau, ysgrifennais fodiwl o\u2019r enw\n<code class=\"docutils literal notranslate\"><span class=\"pre\">structshape</span></code> sy\u2019n darparu swyddogaeth, a elwir hefyd yn <code class=\"docutils literal notranslate\"><span class=\"pre\">structshape</span></code>, sy\u2019n\ncymryd unrhyw fath o strwythur data fel dadl ac yn dychwelyd llinyn sy\u2019n\ncrynhoi ei strwythur. Gallwch ei lawrlwytho o\n<a class=\"reference external\" href=\"https://raw.githubusercontent.com/AllenDowney/ThinkPython/v3/structshape.py\">https://raw.githubusercontent.com/AllenDowney/ThinkPython/v3/structshape.py</a>.</p>", "a[href=\"#ymarferion\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.11. </span>Ymarferion<a class=\"headerlink\" href=\"#ymarferion\" title=\"Link to this heading\">#</a></h2><h3><span class=\"section-number\">14.11.1. </span>Gofyn i gynorthwyydd rhithwir<a class=\"headerlink\" href=\"#gofyn-i-gynorthwyydd-rhithwir\" title=\"Link to this heading\">#</a></h3><p>Mae llawer o eirfa newydd yn y bennod hon. Gall sgwrs gyda chynorthwyydd\nrhithwir helpu i gadarnhau eich dealltwriaeth. Ystyriwch ofyn:</p>", "a[href=\"#id1\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.11.3. </span>Ymarfer<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h3><p>Ysgrifennwch swyddogaeth o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">is_after</span></code> sy\u2019n cymryd dau wrthrych <code class=\"docutils literal notranslate\"><span class=\"pre\">Time</span></code>\nac yn dychwelyd <code class=\"docutils literal notranslate\"><span class=\"pre\">True</span></code> os yw\u2019r amser cyntaf yn hwyrach yn y dydd na\u2019r ail, a\n<code class=\"docutils literal notranslate\"><span class=\"pre\">False</span></code> fel arall.</p><p>Dyma amlinelliad o\u2019r swyddogaeth i\u2019ch helpu ddechrau.</p>", "a[href=\"../glossary.html#term-prototeip-a-chlwt\"]": "<dt id=\"term-prototeip-a-chlwt\">prototeip a chlwt</dt><dd><p>prototype and patch</p></dd>", "a[href=\"#mathau-a-ddiffinnir-gan-raglenwyr\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.1. </span>Mathau a Ddiffinnir gan Raglenwyr<a class=\"headerlink\" href=\"#mathau-a-ddiffinnir-gan-raglenwyr\" title=\"Link to this heading\">#</a></h2><p>Rydym wedi defnyddio llawer o fathau cynhenid Python \u2014 nawr byddwn yn\ndiffinio math newydd. Fel enghraifft gyntaf, byddwn yn creu math o\u2019r enw\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Time</span></code> sy\u2019n cynrychioli amser o\u2019r dydd. Gelwir math a ddiffinnir gan\nraglennydd hefyd yn <strong><a class=\"reference internal\" href=\"../glossary.html#term-dosbarth\"><span class=\"xref std std-term\">dosbarth</span></a></strong>. Mae diffiniad dosbarth yn edrych\nfel hyn:</p>", "a[href=\"#dosbarthiadau-a-swyddogaethau\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14. </span>Dosbarthiadau a Swyddogaethau<a class=\"headerlink\" href=\"#dosbarthiadau-a-swyddogaethau\" title=\"Link to this heading\">#</a></h1><p>Erbyn hyn rydych yn gwybod sut i ddefnyddio swyddogaethau i drefnu cod a\nsut i ddefnyddio mathau cynhenid i drefnu data. Y cam nesaf yw\n<strong><a class=\"reference internal\" href=\"../glossary.html#term-Rhaglennu-Gwrthrych-gyfeiriadol\"><span class=\"xref std std-term\">Rhaglennu Gwrthrych-gyfeiriadol</span></a></strong>, sy\u2019n defnyddio mathau a\nddiffinnir gan raglenwyr i drefnu cod a data fel ei gilydd.</p><p>Mae rhaglennu gwrthrych-gyfeiriadol yn bwnc mawr, felly byddwn yn mynd\nymlaen yn raddol. Yn y bennod hon, byddwn yn dechrau gyda chod nad yw\u2019n\nidiomatig \u2014 hynny yw, nid dyma\u2019r math o god y mae rhaglenwyr profiadol yn\nei ysgrifennu \u2014 ond mae\u2019n lle da i ddechrau. Yn y ddwy bennod nesaf, byddwn\nyn defnyddio nodweddion ychwanegol i ysgrifennu cod mwy idiomatig.</p>", "a[href=\"#copio\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.5. </span>Cop\u00efo<a class=\"headerlink\" href=\"#copio\" title=\"Link to this heading\">#</a></h2><p>Mae\u2019r modiwl <code class=\"docutils literal notranslate\"><span class=\"pre\">copy</span></code> yn darparu swyddogaeth o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">copy</span></code> a all ddyblygu\nunrhyw wrthrych. Gallwn ei fewnforio fel hyn.</p>", "a[href=\"../glossary.html#term-priodoledd\"]": "<dt id=\"term-priodoledd\">priodoledd</dt><dd><p>attribute</p></dd>", "a[href=\"#ymarfer\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.11.2. </span>Ymarfer<a class=\"headerlink\" href=\"#ymarfer\" title=\"Link to this heading\">#</a></h3><p>Ysgrifennwch swyddogaeth o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">subtract_time</span></code> sy\u2019n cymryd dau wrthrych\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Time</span></code> ac yn dychwelyd y cyfnod rhyngddynt mewn eiliadau \u2014 gan dybio mai\ndau amser yr un diwrnod ydynt.</p><p>Dyma amlinelliad o\u2019r swyddogaeth i\u2019ch helpu ddechrau.</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.11.4. </span>Ymarfer<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3><p>Dyma ddiffiniad ar gyfer dosbarth <code class=\"docutils literal notranslate\"><span class=\"pre\">Date</span></code> sy\u2019n cynrychioli dyddiad \u2014 hynny\nyw, blwyddyn, mis, a diwrnod o\u2019r mis.</p>", "a[href=\"../glossary.html#term-datblygu-dylunio-yn-gyntaf\"]": "<dt id=\"term-datblygu-dylunio-yn-gyntaf\">datblygu dylunio-yn-gyntaf</dt><dd><p>design-first development</p></dd>", "a[href=\"#swyddogaethau-pur\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.6. </span>Swyddogaethau Pur<a class=\"headerlink\" href=\"#swyddogaethau-pur\" title=\"Link to this heading\">#</a></h2><p>Gallwn ddefnyddio <code class=\"docutils literal notranslate\"><span class=\"pre\">copy</span></code> i ysgrifennu swyddogaethau pur nad ydynt yn\naddasu eu paramedrau. Er enghraifft, dyma swyddogaeth sy\u2019n cymryd\ngwrthrych <code class=\"docutils literal notranslate\"><span class=\"pre\">Time</span></code> a hyd mewn oriau, munudau, ac eiliadau. Mae\u2019n gwneud copi\no\u2019r gwrthrych gwreiddiol, yn defnyddio <code class=\"docutils literal notranslate\"><span class=\"pre\">increment_time</span></code> i addasu\u2019r copi,\nac yn ei ddychwelyd.</p>", "a[href=\"../glossary.html#term-enghraifft\"]": "<dt id=\"term-enghraifft\">enghraifft</dt><dd><p>instance</p></dd>", "a[href=\"#gofyn-i-gynorthwyydd-rhithwir\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.11.1. </span>Gofyn i gynorthwyydd rhithwir<a class=\"headerlink\" href=\"#gofyn-i-gynorthwyydd-rhithwir\" title=\"Link to this heading\">#</a></h3><p>Mae llawer o eirfa newydd yn y bennod hon. Gall sgwrs gyda chynorthwyydd\nrhithwir helpu i gadarnhau eich dealltwriaeth. Ystyriwch ofyn:</p>", "a[href=\"#gwrthrychau-fel-gwerthoedd-dychwelyd\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.3. </span>Gwrthrychau fel Gwerthoedd Dychwelyd<a class=\"headerlink\" href=\"#gwrthrychau-fel-gwerthoedd-dychwelyd\" title=\"Link to this heading\">#</a></h2><p>Gall swyddogaethau ddychwelyd gwrthrychau. Er enghraifft, mae <code class=\"docutils literal notranslate\"><span class=\"pre\">make_time</span></code>\nyn cymryd paramedrau o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">hour</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">minute</span></code>, a <code class=\"docutils literal notranslate\"><span class=\"pre\">second</span></code>, yn eu storio fel\npriodoleddau mewn gwrthrych <code class=\"docutils literal notranslate\"><span class=\"pre\">Time</span></code>, ac yn dychwelyd y gwrthrych newydd.</p>", "a[href=\"#prototeip-a-chlwt\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.7. </span>Prototeip a Chlwt<a class=\"headerlink\" href=\"#prototeip-a-chlwt\" title=\"Link to this heading\">#</a></h2><p>Yn yr enghraifft flaenorol, mae\u2019n ymddangos bod <code class=\"docutils literal notranslate\"><span class=\"pre\">increment_time</span></code> ac\n<code class=\"docutils literal notranslate\"><span class=\"pre\">add_time</span></code> yn gweithio, ond os rhown gynnig ar enghraifft arall, fe welwn\nnad ydynt yn gwbl gywir.</p><p>Tybiwch eich bod yn cyrraedd y theatr ac yn darganfod bod y ffilm yn\ndechrau am <code class=\"docutils literal notranslate\"><span class=\"pre\">9:40</span></code>, nid <code class=\"docutils literal notranslate\"><span class=\"pre\">9:20</span></code>. Dyma beth sy\u2019n digwydd pan gyfrifwn yr amser\ngorffen wedi\u2019i ddiweddaru.</p>", "a[href=\"../glossary.html#term-diagram-gwrthrych\"]": "<dt id=\"term-diagram-gwrthrych\">diagram gwrthrych</dt><dd><p>object diagram</p></dd>", "a[href=\"#rhestr-termau-r-bennod\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.10. </span>Rhestr Termau\u2019r Bennod<a class=\"headerlink\" href=\"#rhestr-termau-r-bennod\" title=\"Link to this heading\">#</a></h2><p><strong>Rhaglennu Gwrthrych-gyfeiriadol:</strong>\nArddull rhaglennu sy\u2019n defnyddio gwrthrychau i drefnu cod a data.</p><p><strong>dosbarth:</strong>\nMath a ddiffinnir gan raglennydd. Mae diffiniad dosbarth yn creu gwrthrych\ndosbarth newydd.</p>", "a[href=\"../glossary.html#term-penodwr-fformat\"]": "<dt id=\"term-penodwr-fformat\">penodwr fformat</dt><dd><p>format specifier</p></dd>", "a[href=\"../glossary.html#term-gwrthrych-dosbarth\"]": "<dt id=\"term-gwrthrych-dosbarth\">gwrthrych dosbarth</dt><dd><p>class object</p></dd>", "a[href=\"#datblygu-dylunio-yn-gyntaf\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.8. </span>Datblygu Dylunio-yn-Gyntaf<a class=\"headerlink\" href=\"#datblygu-dylunio-yn-gyntaf\" title=\"Link to this heading\">#</a></h2><p>Cynllun amgen yw <strong><a class=\"reference internal\" href=\"../glossary.html#term-datblygu-dylunio-yn-gyntaf\"><span class=\"xref std std-term\">datblygu dylunio-yn-gyntaf</span></a></strong>, sy\u2019n golygu mwy o\ngynllunio cyn creu prototeip. Mewn proses dylunio-yn-gyntaf, weithiau mae\nmewnwelediad lefel-uchel i\u2019r broblem yn gwneud rhaglennu\u2019n llawer haws.</p><p>Yn yr achos hwn, y mewnwelediad yw y gallwn feddwl am wrthrych <code class=\"docutils literal notranslate\"><span class=\"pre\">Time</span></code> fel\nrhif tri-digid yn sail 60 \u2014 a elwir hefyd yn sexagesimal. Y briodoledd\n<code class=\"docutils literal notranslate\"><span class=\"pre\">second</span></code> yw\u2019r \u201cgolofn unedau\u201d, y briodoledd <code class=\"docutils literal notranslate\"><span class=\"pre\">minute</span></code> yw\u2019r \u201cgolofn\ntrigeiniau\u201d, a\u2019r briodoledd <code class=\"docutils literal notranslate\"><span class=\"pre\">hour</span></code> yw\u2019r \u201cgolofn tri-chwe-chant\u201d. Pan\nysgrifennom <code class=\"docutils literal notranslate\"><span class=\"pre\">increment_time</span></code>, roeddem i bob pwrpas yn gwneud adio yn sail\n60, a dyna pam roedd yn rhaid i ni gario o un golofn i\u2019r nesaf.</p>", "a[href=\"../glossary.html#term-Rhaglennu-Gwrthrych-gyfeiriadol\"]": "<dt id=\"term-Rhaglennu-Gwrthrych-gyfeiriadol\">Rhaglennu Gwrthrych-gyfeiriadol</dt><dd><p>object-oriented programming</p></dd>", "a[href=\"../glossary.html#term-enghreifftiad\"]": "<dt id=\"term-enghreifftiad\">enghreifftiad</dt><dd><p>instantiation</p></dd>", "a[href=\"#priodoleddau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.2. </span>Priodoleddau<a class=\"headerlink\" href=\"#priodoleddau\" title=\"Link to this heading\">#</a></h2><p>Gall gwrthrych gynnwys newidynnau, a elwir yn **<a class=\"reference internal\" href=\"../glossary.html#term-priodoledd\"><span class=\"xref std std-term\">priodoledd</span></a>**au. Gallwn\ngreu priodoleddau gan ddefnyddio nodiant dot.</p>", "a[href=\"#dadnamu\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">14.9. </span>Dadnamu<a class=\"headerlink\" href=\"#dadnamu\" title=\"Link to this heading\">#</a></h2><p>Mae Python yn darparu sawl swyddogaeth gynhenid sy\u2019n ddefnyddiol ar gyfer\nprofi a dadnamu rhaglenni sy\u2019n gweithio gyda gwrthrychau. Er enghraifft, os\nnad ydych yn si\u0175r pa fath yw gwrthrych, gallwch ofyn.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
